    if (fechaOk(a.fecha) && a.fecha !== mov.fecha) { props.Fecha = { date: { start: a.fecha } }; cambios.push('fecha → ' + a.fecha); }
    if (CATS.includes(a.categoria) && a.categoria !== mov.cat) { props['Categoría'] = { select: { name: a.categoria } }; cambios.push('categoría → ' + a.categoria); }
    if (['Gasto', 'Ingreso'].includes(a.mov) && a.mov !== mov.tipo) { props.Tipo = { select: { name: a.mov } }; cambios.push(a.mov); }
    if (cambios.length) { ediciones.push({ id: mov.id, cuerpo: { properties: props } }); hechos.push('«' + mov.concepto + '»: ' + cambios.join(', ')); pasos.push({ via: 'edicion', id: mov.id, etiqueta: hechos[hechos.length - 1] }); }
    continue;
  }
  if (a.tipo === 'borrar') {   // a la papelera de Notion: de ahí se puede recuperar
    ediciones.push({ id: mov.id, cuerpo: { archived: true } }); hechos.push('«' + mov.concepto + '» ' + fmtP(mov.monto) + ' a la papelera'); pasos.push({ via: 'edicion', id: mov.id, etiqueta: hechos[hechos.length - 1] });
    continue;
  }
  if (a.tipo === 'corregir') {
    const tipo = ['Gasto', 'Ingreso'].includes(a.mov) ? a.mov : mov.tipo;
    const cat = CATS.includes(a.categoria) ? a.categoria : mov.cat;
    if (tipo !== mov.tipo || cat !== mov.cat) { sd.colaNotion = sd.colaNotion.filter(x => x.id !== mov.id); sd.colaNotion.push({ id: mov.id, tipo, categoria: cat, t: Date.now() }); corregidos++; hechos.push('«' + mov.concepto + '» → ' + tipo + ' · ' + cat); pasos.push({ via: 'notion', id: mov.id, etiqueta: hechos[hechos.length - 1] }); }
  } else if (a.tipo === 'ajuste') {
    if (['favor', 'traslado', 'duplicado'].includes(a.clas)) { sd.ajustes[mov.id] = { clas: a.clas, tipo: mov.tipo, monto: mov.monto, fecha: mov.fecha, cat: mov.cat, concepto: mov.concepto, nota: String(a.nota || 'lo dijo la familia').slice(0, 120) }; ajustados++; hechos.push('«' + mov.concepto + '» ya no cuenta (' + a.clas + ')'); pasos.push({ via: 'local', etiqueta: hechos[hechos.length - 1] }); }
    else if (a.clas === 'real' && sd.ajustes[mov.id]) { delete sd.ajustes[mov.id]; ajustados++; hechos.push('«' + mov.concepto + '» vuelve a contar'); pasos.push({ via: 'local', etiqueta: hechos[hechos.length - 1] }); }
  }
}
if (sd.memoria.length > 150) sd.memoria = sd.memoria.slice(-150);
// el «✅ Listo» NO se arma aquí: lo arma «Resultado consulta» con lo que Notion de verdad confirmó (C1)
return [{ json: { ok: true, consulta: true, respuesta: texto, propuesta, aprendidos, corregidos, ajustados, editados: ediciones.length, ediciones, app, pasos, saber: sd.memoria, ajustes: sd.ajustes } }];

// los cambios de datos que la familia confirmó en «Pregúntale a Armoni» (editar o mandar a la papelera), uno por movimiento
let ed = [];
try { ed = $('Guardar consulta').first().json.ediciones || []; } catch (e) {}
const l = ed.filter(x => x && x.id && x.cuerpo).map(x => ({ json: x }));
return l.length ? l : [{ json: { vacio: true } }];

// Notion ya respondió: se quita de la cola SOLO lo que Notion confirmó; lo que falló suma un intento y se reintenta en la próxima llamada (C2).
// Tras 5 intentos fallidos sale de la cola y queda en sd.colaFallida (se avisa en «notionFallido»), para no reintentar para siempre algo que Notion rechaza.
const sd = $getWorkflowStaticData('global');
sd.colaNotion = Array.isArray(sd.colaNotion) ? sd.colaNotion : [];
sd.colaFallida = Array.isArray(sd.colaFallida) ? sd.colaFallida : [];
const nid = id => String(id || '').replace(/-/g, '').toLowerCase();
let enviados = [];
try { enviados = $('Correcciones').all().map(i => i.json).filter(x => x && x.id && !x.vacio); } catch (e) {}
// una página de Notion de verdad (no un error ni el ítem de entrada que pasó de largo)
const esPagina = j => j && j.id && !j.error && (j.url || j.object === 'page' || j.properties);
const okIds = new Set($input.all().map(i => i.json).filter(esPagina).map(j => nid(j.id)));
const mandados = new Set(enviados.map(x => nid(x.id)));
const ok = [], fallidos = [];
const ahora = Date.now();
sd.colaNotion = sd.colaNotion.filter(x => {
  const k = nid(x.id);
  if (!mandados.has(k)) return true;              // no se mandó esta vez: sigue en cola
  delete x.enviando;
  if (okIds.has(k)) { ok.push(x.id); return false; }
  x.intentos = (x.intentos || 0) + 1; x.ultimoIntento = ahora; fallidos.push(x.id);
  if (x.intentos >= 5) { sd.colaFallida.push({ id: x.id, tipo: x.tipo, categoria: x.categoria, intentos: x.intentos, t: new Date().toISOString() }); return false; }
  return true;
});
sd.colaFallida = sd.colaFallida.slice(-50);
let consulta = false;
try { consulta = $('Validar').first().json.accion === 'consultar'; } catch (e) {}
return [{ json: { consulta, ok, fallidos, pendientes: sd.colaNotion.length } }];

// Respuesta de «Pregúntale a Armoni» DESPUÉS de escribir en Notion (C1): el «✅ Listo» dice solo lo que de verdad quedó guardado
// y se avisa lo que no se pudo (lo de la cola se reintenta solo; una edición fallida hay que pedirla de nuevo).
const _respaldo = sd => sd.esperaRespaldo ? null : { v: 3, flujo: 'armoni-preguntas', t: Date.now(), memoria: sd.memoria || [], ajustes: sd.ajustes || {}, decisiones: (sd.decisiones || []).slice(-80), patrones: sd.patrones || {}, alias: sd.alias || {}, nivel: sd.nivel || '',
  lugarPreg: sd.lugarPreg || {}, parPreg: sd.parPreg || {}, colaNotion: (sd.colaNotion || []).map(x => ({ id: x.id, tipo: x.tipo, categoria: x.categoria, intentos: x.intentos || 0 })), casos: (sd.preguntas || []).filter(q => q.tipo === 'caso').map(q => ({ id: q.id, estado: q.estado })) };
const _meta = (sd, conRespaldo) => ({ flujo: 'armoni-preguntas', version: 3, respaldo: conRespaldo === false ? null : _respaldo(sd), esperaRespaldo: !!sd.esperaRespaldo, colaPendiente: (sd.colaNotion || []).length, notionFallido: (sd.colaFallida || []).length });
const sd = $getWorkflowStaticData('global');
const g = $('Guardar consulta').first().json;
const nid = id => String(id || '').replace(/-/g, '').toLowerCase();
let okCola = new Set();
try { okCola = new Set(($('Confirmar cola').first().json.ok || []).map(nid)); } catch (e) {}
const okEd = new Set();
try { $('Editar en Notion').all().forEach(i => { const j = i.json; if (j && j.id && !j.error && (j.object === 'page' || j.url || j.properties)) okEd.add(nid(j.id)); }); } catch (e) {}   // si no hubo ediciones, el nodo no corrió
const enCola = new Set((sd.colaNotion || []).map(x => nid(x.id)));
const bien = [], pendiente = [], mal = [];
for (const p of (g.pasos || [])) {
  if (p.via === 'notion') { if (okCola.has(nid(p.id))) bien.push(p); else if (enCola.has(nid(p.id))) pendiente.push(p); else mal.push(p); }
  else if (p.via === 'edicion') { if (okEd.has(nid(p.id))) bien.push(p); else mal.push(p); }
  else bien.push(p);   // «local» (ya quedó en Armoni) y «app» (lo hace la app al recibir la respuesta)
}
let t = String(g.respuesta || '').trim();
if (bien.length) t += '\n\n✅ Listo: ' + bien.map(p => p.etiqueta).join(' · ') + '.';
if (pendiente.length) t += '\n\n⏳ Todavía no quedó en Notion: ' + pendiente.map(p => p.etiqueta).join(' · ') + '. Lo vuelvo a intentar solo en la próxima revisión.';
if (mal.length) t += '\n\n⚠️ No pude guardar en Notion: ' + mal.map(p => p.etiqueta).join(' · ') + '. Pídemelo otra vez en un ratico.';
if (g.aprendidos) t += '\n\n🧠 Lo aprendí para la próxima.';
const corregidos = (g.pasos || []).filter(p => p.via === 'notion' && okCola.has(nid(p.id))).length;
const editados = (g.pasos || []).filter(p => p.via === 'edicion' && okEd.has(nid(p.id))).length;
const r = Object.assign({}, g, { respuesta: t || 'Listo.', corregidos, editados, guardados: bien.map(p => p.etiqueta), pendientesNotion: pendiente.map(p => p.etiqueta), fallidos: mal.map(p => p.etiqueta), saber: sd.memoria || [], ajustes: sd.ajustes || {} }, _meta(sd));
delete r.pasos;
return [{ json: r }];
